# MECH 361 (Fluid Mechanics II, Dr. Essel, Fall 2026) — theory question bank.
# Written from the lecture slides (Munson 9e: Ch 1 review, 6.1–6.6, 6.8–6.9, Ch 8, Ch 9, Ch 11) and the exam formula sheet.
#
# House rules (from Abboud's prep brief, see STYLE.md):
#  - Every formula is tagged: (sheet p.N[, row]) | derived in ≤4 lines | (definition, not on the sheet) | (know this) [only Kutta–Joukowski].
#  - Notation follows the formula sheet: source v_r = m/(2πr) with m = Q (per unit depth); vortex v_θ = Γ/(2πr); BL δ/x = 5.48/√Re_x.
#  - One formula per line, every symbol defined on first use, every sign explained in words, units on numeric answers.
C = "mech361"
S1, S2, S3 = "(sheet p.1)", "(sheet p.2)", "(sheet p.3)"
DEF, KNOW = "(definition, not on the sheet)", "(know this: the one result allowed without derivation)"
L = lambda n, t: f"Lecture {n:02d} – {t}" if isinstance(n, int) else f"Lecture {n} – {t}"
Q = []
def add(kind, id, topic, q, exp, src, **kw):
    d = dict(id=f"m361-{id}", course=C, topic=topic, type=kind, question=q, explanation=exp, source=src); d.update(kw); Q.append(d)
def mcq(id, topic, q, choices, ans, exp, src, fig=None): add("mcq", id, topic, q, exp, src, choices=choices, answer=ans, figure=fig)
def tf(id, topic, q, ans, exp, src, fig=None): add("tf", id, topic, q, exp, src, answer=ans, figure=fig)
def sa(id, topic, q, ans, exp, src, kw=(), fig=None): add("short", id, topic, q, exp, src, answer=ans, keywords=list(kw), figure=fig)

# ───────────────────────── Exam habits (from the marked midterm) ─────────────────────────
T = "Exam habits"; s = "Midterm feedback"
tf("hb-01", T, "On the final, it's fine to skip a 'trivial' step like cancelling γz if the answer is right.", False, "The marker wrote \"no marks for missing steps\".\nSet every equation up in full, say what cancels and why, then isolate.", s)
sa("hb-02", T, "Before taking a limit of an expression like $\\frac{m}{2\\pi}\\theta$ or $\\frac{\\sin\\theta}{r}$ as you approach a body or axis, what should you write first?", "Rewrite in Cartesian form, e.g. write $r\\sin\\theta=y$, so it's clear which quantity goes to zero.", "Post-midterm habit #1.\nExample: on the axis, $y\\to0$ while $x$ stays finite, so $\\theta\\to0$ or $\\pi$ depending on the side.", s, ["r sin θ = y", "then take the limit"])
sa("hb-03", T, "A question asks for 'the shear stress on the plate'. What must you check before computing $\\tau=\\mu\\,du/dy$?", "Which surface (top or bottom plate, which fluid) and at which $y$ it means. Evaluate $du/dy$ at that wall, and give the direction of the force on that surface.", "Post-midterm habit #2.\n$\\tau=\\mu\\,du/dy$ " + DEF + "\nThe same profile gives different $\\tau$ (and opposite force directions) on the two plates.", s, ["which surface", "which y", "direction"])
tf("hb-04", T, "Every final numerical answer needs a unit.", True, "Post-midterm habit #3.\nFor example, write $q=0.40\\ \\mathrm{m^2/s}$ (per unit depth), not $q=0.40$.", s)

# ───────────────────────── Ch 1 review ─────────────────────────
T = "Fluid basics (Ch 1)"; s = L(2, "Introduction & Fluid Kinematics")
tf("c1-01", T, "A solid deforms when a shear stress is applied, but unlike a fluid its deformation is not continuous.", True, "A fluid deforms continuously under shear stress, however small.", s)
mcq("c1-02", T, "For a Newtonian fluid, shear stress is:", ["Linearly proportional to the rate of shear strain", "Proportional to the shear strain itself", "Independent of the velocity gradient", "Proportional to the square of the velocity gradient"], 0, "$\\tau=\\mu\\,\\dfrac{du}{dy}$ " + DEF + "\n$\\tau$ = shear stress (Pa)\n$\\mu$ = dynamic viscosity (Pa·s)\n$du/dy$ = rate of shear strain (1/s)", s)
mcq("c1-03", T, "Ketchup and paint get easier to stir the harder you shear them. They are:", ["Shear-thinning (pseudoplastic)", "Shear-thickening (dilatant)", "Bingham plastics", "Newtonian"], 0, "Shear-thinning: apparent viscosity decreases as shear rate increases.", s)
mcq("c1-04", T, "A water–cornstarch mixture (or quicksand) is an example of a:", ["Shear-thickening (dilatant) fluid", "Shear-thinning fluid", "Bingham plastic", "Newtonian fluid"], 0, "Apparent viscosity increases with shear rate.", s)
tf("c1-05", T, "Toothpaste and mayonnaise can withstand a finite yield stress without flowing, which makes them Bingham plastics.", True, "Below the yield stress they behave like a solid. Above it they flow.", s)
sa("c1-06", T, "List the five basic laws used to analyze fluid problems.", "Conservation of mass, Newton's 2nd law (linear momentum), angular momentum principle, 1st law of thermodynamics, 2nd law of thermodynamics.", "Not every problem needs all five. Some also need an equation of state and boundary conditions such as no-slip.", s, ["mass", "linear momentum", "angular momentum", "1st law", "2nd law"])
mcq("c1-07", T, "Which statement about a control volume is TRUE?", ["Mass can cross its control surface", "It always contains the same fluid particles", "The basic laws apply to it directly without modification", "Its boundary can never move"], 0, "A system is a fixed mass: no mass crosses its boundary.\nA control volume (CV) is a region in space, and mass flows through it.\nThe basic laws are written for systems. The Reynolds transport theorem converts them to a CV.", s)
mcq("c1-08", T, "Following one fluid particle as it moves through the flow is the:", ["Lagrangian approach", "Eulerian approach", "Integral approach", "Control-volume approach"], 0, "The Eulerian approach describes the field at fixed points in space. It's the usual one in this course.", s)
tf("c1-09", T, "The integral approach gives the detailed velocity distribution in a pipe, while the differential approach only gives bulk quantities like average velocity.", False, "It's the reverse.\nIntegral approach → bulk quantities (e.g. average velocity, total force).\nDifferential approach → the detailed field (e.g. $u(r)$).", s)

# ───────────────────────── 6.1 Kinematics ─────────────────────────
T = "Fluid kinematics (6.1)"; s2 = L(2, "Fluid Kinematics"); s3 = L(3, "Fluid Kinematics"); s4 = L(4, "Fluid Kinematics"); s5 = L(5, "Kinematics & Conservation of Mass")
tf("k-01", T, "A flow whose velocity at every point does not change with time is steady, even if the velocity varies from point to point.", True, "Steady = no time dependence.\nUniform = no change in space.\nThe two properties are independent.", s2)
mcq("k-02", T, "The $x$-acceleration on the sheet, $a_x=\\frac{\\partial u}{\\partial t}+u\\frac{\\partial u}{\\partial x}+v\\frac{\\partial u}{\\partial y}+w\\frac{\\partial u}{\\partial z}$, is made of:", ["Local acceleration (first term) + convective acceleration (the rest)", "Normal + tangential acceleration", "Linear + angular acceleration", "Pressure + viscous acceleration"], 0, "$a_x$ material derivative " + S1 + "\n$\\partial u/\\partial t$ = local term (unsteadiness at a fixed point)\n$u\\,\\partial u/\\partial x+\\dots$ = convective terms (the particle moves to where the velocity is different)", s2)
tf("k-03", T, "In a steady flow, fluid particles cannot accelerate.", False, "Steady flow only removes $\\partial u/\\partial t$.\nThe convective terms can still be nonzero, e.g. flow speeding up through a nozzle.", s2)
sa("k-04", T, "Name the four types of motion a fluid element can undergo.", "Translation, rotation, linear deformation, angular deformation.", "Translation and rotation are rigid-body motions.\nLinear and angular deformation change the element's size or shape.", s3, ["translation", "rotation", "linear deformation", "angular deformation"])
mcq("k-05", T, "The volumetric dilatation rate $\\frac1V\\frac{dV}{dt}$ equals:", ["$\\dfrac{\\partial u}{\\partial x}+\\dfrac{\\partial v}{\\partial y}+\\dfrac{\\partial w}{\\partial z}$", "$\\dfrac{\\partial v}{\\partial x}-\\dfrac{\\partial u}{\\partial y}$", "$\\dfrac{\\partial v}{\\partial x}+\\dfrac{\\partial u}{\\partial y}$", "$\\dfrac12\\left(\\dfrac{\\partial v}{\\partial x}-\\dfrac{\\partial u}{\\partial y}\\right)$"], 0, "$\\frac1V\\frac{dV}{dt}=\\nabla\\cdot\\vec V$ " + DEF + "\nIt's the sum of the three linear strain rates.\nIt equals the left side of the Cartesian continuity equation " + S1 + ".", s3)
mcq("k-06", T, "What is the volumetric dilatation rate in an incompressible flow?", ["Zero", "Constant but nonzero", "One", "Negative"], 0, "Incompressible: each element keeps its volume.\n$\\nabla\\cdot\\vec V=0$\nThis is exactly the continuity equation on the sheet " + S1 + ". (Engineers at Work 6.1)", s4)
tf("k-07", T, "When air is compressed in a cylinder by a piston, the volumetric dilatation rate of the air is negative.", True, "The elements shrink, so $dV/dt<0$.\nNegative here means losing volume. (Engineers at Work 6.1)", s4)
mcq("k-08", T, "Vorticity $\\vec\\zeta$ and the angular velocity $\\vec\\omega$ of a fluid particle are related by:", ["$\\vec\\zeta=2\\vec\\omega$", "$\\vec\\zeta=\\vec\\omega$", "$\\vec\\zeta=\\tfrac12\\vec\\omega$", "$\\vec\\zeta=\\nabla\\cdot\\vec V$"], 0, "$\\omega_z=\\tfrac12\\left(\\dfrac{\\partial v}{\\partial x}-\\dfrac{\\partial u}{\\partial y}\\right)$ " + S1 + "\n$\\zeta=2\\omega=\\nabla\\times\\vec V$ " + DEF, s3)
mcq("k-09", T, "A 2-D flow in the $x$–$y$ plane is irrotational when:", ["$\\dfrac{\\partial v}{\\partial x}=\\dfrac{\\partial u}{\\partial y}$", "$\\dfrac{\\partial u}{\\partial x}=-\\dfrac{\\partial v}{\\partial y}$", "$\\dfrac{\\partial v}{\\partial x}=-\\dfrac{\\partial u}{\\partial y}$", "$u=v$"], 0, "Set $\\omega_z=0$ " + S1 + ":\n$\\tfrac12\\left(\\dfrac{\\partial v}{\\partial x}-\\dfrac{\\partial u}{\\partial y}\\right)=0$\n$\\dfrac{\\partial v}{\\partial x}=\\dfrac{\\partial u}{\\partial y}$", s3)
tf("k-10", T, "The 2-D velocity field $u=3x-y$, $v=2y$ is irrotational.", False, "$\\omega_z=\\tfrac12\\left(\\dfrac{\\partial v}{\\partial x}-\\dfrac{\\partial u}{\\partial y}\\right)$ " + S1 + "\n$\\partial v/\\partial x=0$\n$\\partial u/\\partial y=-1$\n$\\omega_z=\\tfrac12(0-(-1))=0.5\\ \\mathrm{s^{-1}}\\neq0$, so the flow is rotational (counter-clockwise, since it's positive). (Engineers at Work 6.2)", s5)
mcq("k-11", T, "The rate of angular deformation in the $x$–$y$ plane is:", ["$\\dot\\gamma_{xy}=\\dfrac{\\partial v}{\\partial x}+\\dfrac{\\partial u}{\\partial y}$", "$\\dot\\gamma_{xy}=\\dfrac{\\partial v}{\\partial x}-\\dfrac{\\partial u}{\\partial y}$", "$\\dot\\gamma_{xy}=\\dfrac{\\partial u}{\\partial x}+\\dfrac{\\partial v}{\\partial y}$", "$\\dot\\gamma_{xy}=\\tfrac12\\left(\\dfrac{\\partial v}{\\partial x}-\\dfrac{\\partial u}{\\partial y}\\right)$"], 0, "$\\dot\\gamma_{xy}=\\dfrac{\\partial v}{\\partial x}+\\dfrac{\\partial u}{\\partial y}$ " + S1 + "\nIt's the rate at which the angle between two initially perpendicular lines closes.\n$\\tau_{yx}=\\mu\\,\\dot\\gamma_{xy}$ " + S1, s4)
tf("k-12", T, "For $u=Uy/b$ between plates, the flow is both rotational and undergoing angular deformation.", True, "$\\partial u/\\partial y=U/b$ and $\\partial v/\\partial x=0$\n$\\omega_z=\\tfrac12(0-U/b)=-\\dfrac{U}{2b}$ " + S1 + " (negative = clockwise)\n$\\dot\\gamma_{xy}=0+U/b=U/b$ " + S1 + "\nThe dilatation is zero. (Example 6.3)", s4)
mcq("k-13", T, "What is the simplest type of motion a fluid particle can undergo?", ["Translation", "Rotation", "Linear deformation", "Angular deformation"], 0, "Engineers at Work 6.2.", s4)
tf("k-14", T, "The polar $\\omega_z$ on the formula sheet has a misprint, so you should use $\\omega_z=\\frac12\\left(\\frac1r\\frac{\\partial(rv_\\theta)}{\\partial r}-\\frac1r\\frac{\\partial v_r}{\\partial\\theta}\\right)$.", True, "The sheet's polar $\\omega_z$ swaps $v_r$ and $v_\\theta$ in the first term " + S1 + ".\nUse the correct form above and say so once on the exam.", s3)

# ───────────────────────── 6.2 Continuity & ψ ─────────────────────────
T = "Continuity & stream function (6.2)"; s = L(5, "Kinematics & Conservation of Mass")
mcq("cm-01", T, "The general differential continuity equation is:", ["$\\dfrac{\\partial\\rho}{\\partial t}+\\nabla\\cdot(\\rho\\vec V)=0$", "$\\nabla\\cdot\\vec V=0$", "$\\nabla\\times\\vec V=0$", "$\\rho\\dfrac{D\\vec V}{Dt}=-\\nabla p$"], 0, "General form " + DEF + "\nThe sheet gives only the incompressible forms (Cartesian and cylindrical) " + S1 + ".", s)
mcq("cm-02", T, "For steady compressible flow, the continuity equation reduces to:", ["$\\nabla\\cdot(\\rho\\vec V)=0$", "$\\nabla\\cdot\\vec V=0$", "$\\partial\\rho/\\partial t=0$ only", "$\\rho\\vec V=$ constant everywhere"], 0, "Steady → $\\partial\\rho/\\partial t=0$.\nThe density can still vary in space, so $\\rho$ stays inside the divergence.", s)
mcq("cm-03", T, "In 2-D Cartesian flow, the stream function gives:", ["$u=\\dfrac{\\partial\\psi}{\\partial y}$, $v=-\\dfrac{\\partial\\psi}{\\partial x}$", "$u=-\\dfrac{\\partial\\psi}{\\partial y}$, $v=\\dfrac{\\partial\\psi}{\\partial x}$", "$u=\\dfrac{\\partial\\psi}{\\partial x}$, $v=\\dfrac{\\partial\\psi}{\\partial y}$", "$\\vec V=\\nabla\\psi$"], 0, "$u=\\partial\\psi/\\partial y$ " + S1 + "\n$v=-\\partial\\psi/\\partial x$ " + S1 + "\nThis definition satisfies continuity automatically.", s)
tf("cm-04", T, "In 2-D incompressible flow, lines of constant stream function are streamlines.", True, "Along a streamline $d\\psi=0$. (Engineers at Work 6.2)", s)
tf("cm-05", T, "The volume flow rate per unit depth between two streamlines is $q=\\psi_2-\\psi_1$.", True, "$q=\\psi_2-\\psi_1$ " + DEF + "\nNo flow crosses a streamline, so $\\Delta\\psi$ fixes the flow between them.\nThe sign tells you the direction: positive when the flow crosses left-to-right looking from 1 to 2.", s)
mcq("cm-06", T, "In polar coordinates the stream function gives:", ["$v_r=\\dfrac1r\\dfrac{\\partial\\psi}{\\partial\\theta}$, $v_\\theta=-\\dfrac{\\partial\\psi}{\\partial r}$", "$v_r=\\dfrac{\\partial\\psi}{\\partial r}$, $v_\\theta=\\dfrac1r\\dfrac{\\partial\\psi}{\\partial\\theta}$", "$v_r=-\\dfrac{\\partial\\psi}{\\partial r}$, $v_\\theta=\\dfrac1r\\dfrac{\\partial\\psi}{\\partial\\theta}$", "$v_r=r\\dfrac{\\partial\\psi}{\\partial\\theta}$, $v_\\theta=\\dfrac{\\partial\\psi}{\\partial r}$"], 0, "$v_r=\\frac1r\\,\\partial\\psi/\\partial\\theta$ " + S1 + "\n$v_\\theta=-\\partial\\psi/\\partial r$ " + S1 + "\nCompare: $v_r=\\partial\\phi/\\partial r$ and $v_\\theta=\\frac1r\\,\\partial\\phi/\\partial\\theta$ " + S1, s)
sa("cm-07", T, "How do you check whether a stream function exists for a given 2-D velocity field?", "Check incompressible continuity: $\\partial u/\\partial x+\\partial v/\\partial y=0$ " + S1 + ". If it holds, ψ exists.", "ψ is built to satisfy continuity.\nIrrotationality is NOT required (that's the condition for φ). (Example 6.5)", s, ["continuity satisfied", "irrotational not needed"])
mcq("cm-08", T, "For $\\psi=4x^2y-y^3$, the velocity component $v$ is:", ["$-8xy$", "$4x^2-3y^2$", "$8xy$", "$-4x^2+3y^2$"], 0, "$v=-\\dfrac{\\partial\\psi}{\\partial x}$ " + S1 + "\n$\\dfrac{\\partial\\psi}{\\partial x}=8xy$ (the $y^3$ term has no $x$)\n$v=-8xy$\nIn the first quadrant $v<0$, meaning the flow points downward. (Engineers at Work 6.2)", s)
sa("cm-09", T, "Given $u=2x$, show the steps to find ψ.", "1) $u=\\partial\\psi/\\partial y=2x$ " + S1 + "\n2) Integrate in $y$: $\\psi=2xy+f(x)$\n3) $v=-\\partial\\psi/\\partial x=-2y-f'(x)$\n4) Compare with the given $v$ (here $v=-2y$), so $f'(x)=0$ and $f$ = const (set 0)\n$\\psi=2xy$", "Always show the $+f(x)$ and then find $f'(x)$. Dropping it loses marks.", s, ["integrate u in y", "+ f(x)", "find f′(x) from v"])

# ───────────────────────── 6.3–6.4 Momentum & inviscid ─────────────────────────
T = "Momentum & inviscid flow (6.3–6.4)"; s6 = L(6, "Linear Momentum & Inviscid Flow"); s7 = L(7, "LME & Potential Flow")
mcq("mo-01", T, "The forces acting on a differential fluid element are:", ["Body forces (gravity) and surface forces (normal and shear stresses)", "Only pressure forces", "Only gravity", "Inertial and centrifugal forces"], 0, "Surface forces come from the stress field: normal stresses $\\sigma$ and shear stresses $\\tau$.", s6)
tf("mo-02", T, "In the stress notation $\\tau_{yx}$, the first index gives the direction of the normal to the plane and the second gives the direction the stress acts in.", True, "$\\tau_{yx}$ acts on a plane whose normal is $y$, pointing in the $x$-direction.\n$\\tau_{yx}=\\mu\\left(\\dfrac{\\partial u}{\\partial y}+\\dfrac{\\partial v}{\\partial x}\\right)$ " + S1, s6)
mcq("mo-03", T, "The general differential momentum equations written in terms of stresses are called:", ["Cauchy's equations", "Euler's equations", "Navier–Stokes equations", "Bernoulli equations"], 0, "Inviscid stresses → Euler's equations " + S1 + ".\nNewtonian stresses → Navier–Stokes " + S1 + ".", s6)
mcq("mo-04", T, "A flow is called inviscid when:", ["Shearing stresses are negligible", "The velocity is negligible", "No acceleration occurs", "The density is constant"], 0, "With $\\mu\\approx0$ the only stress left is pressure. (Engineers at Work)", s7)
mcq("mo-05", T, "The equations of motion for an inviscid flow are called:", ["Euler's equations", "Cauchy's equations", "Newton's equations", "Stokes' equations"], 0, "Euler (2D, no gravity) " + S1 + ":\n$\\rho\\left(\\dfrac{\\partial u}{\\partial t}+u\\dfrac{\\partial u}{\\partial x}+v\\dfrac{\\partial u}{\\partial y}\\right)=-\\dfrac{\\partial p}{\\partial x}$", s7)
tf("mo-06", T, "All inviscid flows are irrotational, but not all irrotational flows are inviscid.", False, "The first part is false: an inviscid flow can still be rotational (vorticity is carried along, not destroyed, when viscosity is zero).\nIn this course, irrotational (potential) flows are modelled as inviscid. (Engineers at Work)", s7)
sa("mo-07", T, "State the assumptions behind the sheet's Bernoulli equation $p_1+\\tfrac12\\rho V_1^2=p_2+\\tfrac12\\rho V_2^2$.", "Steady, incompressible, inviscid flow, with no gravity term (horizontal, or γz cancels). Applies along a streamline, or between any two points if the flow is irrotational.", "Bernoulli (no gravity) " + S1 + "\nIn a solution: write the full form with γz, name points 1 and 2, give each term's value with a reason, cancel with a reason, then isolate.", s6, ["steady", "incompressible", "inviscid", "streamline / irrotational", "γz cancels"])
tf("mo-08", T, "For irrotational flow, the Bernoulli equation can be applied between any two points, not just along one streamline.", True, "Irrotationality makes the Bernoulli constant the same everywhere.\nThat's why potential-flow pressure problems can go from far upstream ($V=U$) to any point.", s7)

# ───────────────────────── 6.5–6.6 Potential flow ─────────────────────────
T = "Potential flow (6.5–6.6)"; s7 = L(7, "Potential Flow – Uniform Flow"); s8 = L(8, "Source, Sink & Vortex"); s9 = L(9, "Vortex, Doublet & Superposition"); s10 = L(10, "Superposition"); s11 = L(11, "Superposition & Navier–Stokes")
sa("pf-01", T, "What three properties define a potential flow, and which equation governs it?", "Inviscid, incompressible and irrotational. Laplace's equation: $\\nabla^2\\phi=0$ (and $\\nabla^2\\psi=0$ in 2-D).", "Laplace comes from substituting $\\vec V=\\nabla\\phi$ " + S1 + " into incompressible continuity " + S1 + ".\nPressure then comes from Bernoulli " + S1 + ".", s7, ["inviscid", "incompressible", "irrotational", "Laplace"])
mcq("pf-02", T, "The major advantage of Laplace's equation over the momentum equations is that it is:", ["Linear, so solutions can be superposed", "Nonlinear, so it captures turbulence", "First order", "Valid for viscous flows"], 0, "Because it's linear, the block solutions on the sheet (uniform, source, vortex, doublet) can be added together " + S2 + ".", s9)
tf("pf-03", T, "The velocity potential exists only for irrotational flows, while the stream function (2-D) exists for any incompressible flow.", True, "$\\vec V=\\nabla\\phi$ automatically gives zero vorticity.\nψ only needs continuity.", s7)
tf("pf-04", T, "In a potential flow, lines of constant φ are perpendicular to streamlines.", True, "$\\nabla\\phi$ is parallel to $\\vec V$, and $\\vec V$ is tangent to the streamlines.", s7)
mcq("pf-05", T, "Using the sheet's notation (source of strength $m$, where $m=Q$ per unit depth), the radial velocity is:", ["$v_r=\\dfrac{m}{2\\pi r}$", "$v_r=\\dfrac{m}{r}$", "$v_r=\\dfrac{m}{2\\pi r^2}$", "$v_r=2\\pi m r$"], 0, "Source row " + S2 + ":\n$\\phi=\\dfrac{m}{2\\pi}\\ln r$\n$\\psi=\\dfrac{m}{2\\pi}\\theta$\n$v_r=\\dfrac{m}{2\\pi r}$, $v_\\theta=0$\n$v_r>0$ means outward. A sink has $m<0$ (inward).", s8, fig="source")
mcq("pf-06", T, "The streamlines of a free vortex are:", ["Concentric circles", "Radial lines", "Parallel straight lines", "Hyperbolas"], 0, "Vortex row " + S2 + ":\n$\\psi=-\\dfrac{\\Gamma}{2\\pi}\\ln r$\n$v_\\theta=\\dfrac{\\Gamma}{2\\pi r}$, $v_r=0$\n$\\Gamma>0$ means counter-clockwise rotation.", s8, fig="vortex")
mcq("pf-07", T, "Which statement about free and forced vortices is correct?", ["A free vortex ($v_\\theta=\\Gamma/2\\pi r$) is irrotational. A forced vortex ($v_\\theta=K_1r$) is rotational.", "Both are irrotational", "A free vortex is rotational. A forced vortex is irrotational.", "Both are rotational"], 0, "Free and forced vortex rows " + S2 + ".\nCorrect polar $\\omega_z=\\tfrac12\\left(\\frac1r\\frac{\\partial(rv_\\theta)}{\\partial r}-\\frac1r\\frac{\\partial v_r}{\\partial\\theta}\\right)$ " + S1 + " (sheet misprint corrected).\nFree: $rv_\\theta$ = const, so $\\omega_z=0$.\nForced: $rv_\\theta=K_1r^2$, so $\\omega_z=K_1$.", s9)
sa("pf-08", T, "What is a combined (Rankine) vortex? Give an example.", "A forced (rotational) vortex core with a free (irrotational) vortex outside it. Example: a tornado.", "$v_\\theta=K_1r$ inside the core, then $v_\\theta=\\Gamma/2\\pi r$ outside " + S2 + ".\nThe speed peaks at the edge of the core.", s9, ["forced core", "free outside", "tornado"])
mcq("pf-09", T, "Circulation Γ is defined as:", ["$\\oint\\vec V\\cdot d\\vec s$ around a closed curve", "The flow rate through a closed curve", "The curl of the velocity at a point", "The area integral of pressure"], 0, "$\\Gamma=\\oint\\vec V\\cdot d\\vec s$ " + DEF + "\nFor the free vortex: $\\Gamma=\\int_0^{2\\pi}\\frac{\\Gamma}{2\\pi r}\\,r\\,d\\theta=\\Gamma$, which checks out.", s9)
tf("pf-10", T, "The circulation around any closed path that does NOT enclose the centre of a free vortex is zero.", True, "The free vortex is irrotational everywhere except the singular point at $r=0$.", s9)
mcq("pf-11", T, "A doublet is formed by:", ["Bringing a source and an equal sink together while keeping (strength × spacing) fixed", "Adding a vortex to a uniform flow", "Adding two equal sources", "Adding a source to a uniform flow"], 0, "Doublet row " + S2 + ".\nIts streamlines are circles tangent to the $x$-axis at the origin.", s9, fig="doublet")
mcq("pf-12", T, "Which two blocks superpose to give this flow?", ["Uniform flow + source", "Uniform flow + doublet", "Uniform flow + source + sink", "Source + vortex"], 0, "This is the Rankine half-body.\nOne stagnation point upstream at $x=-b$. The body stays open downstream.\n$\\psi=Ur\\sin\\theta+\\dfrac{m}{2\\pi}\\theta$ (uniform + source rows " + S2 + ")", s9, fig="half_body")
mcq("pf-13", T, "Which blocks superpose to give this closed body?", ["Uniform flow + source + equal sink", "Uniform flow + source", "Uniform flow + doublet", "Uniform flow + vortex"], 0, "This is the Rankine oval.\nSource at $x=-a$, sink at $x=+a$.\nTwo stagnation points at $x=\\pm\\ell$.", s10, fig="rankine_oval")
mcq("pf-14", T, "Which blocks superpose to give this flow?", ["Uniform flow + doublet", "Uniform flow + source", "Uniform flow + vortex only", "Source + sink + vortex"], 0, "Flow around a circular cylinder.\nAdd a vortex as well and you get a rotating cylinder with lift.", s10, fig="cylinder")
mcq("pf-15", T, "On the surface of a cylinder in potential flow, the speed is largest at:", ["Top and bottom ($\\theta=\\pm90^\\circ$), where it equals $2U$", "The front stagnation point", "$\\theta=45^\\circ$, where it equals $\\sqrt2U$", "The rear, where it equals $U$"], 0, "Rewrite: $\\psi=U\\sin\\theta\\,(r-a^2/r)$\n$v_\\theta=-\\partial\\psi/\\partial r$ " + S1 + "\n$=-U\\sin\\theta\\,(1+a^2/r^2)$\nPut $r=a$: $v_{\\theta s}=-2U\\sin\\theta$\nAt $\\theta=90^\\circ$, $v_\\theta=-2U$: negative θ-direction at the top = to the right (downstream).", s10, fig="cylinder")
sa("pf-16", T, "State d'Alembert's paradox.", "In potential (inviscid) flow, a body such as a cylinder has zero drag, which contradicts experiments.", "The potential-flow surface pressure is symmetric front to back, so it integrates to zero.\nReal flows have boundary layers and separation that break the symmetry.", s10, ["zero drag", "inviscid", "contradicts experiment", "separation"])
mcq("pf-17", T, "Adding a vortex of circulation Γ to the flow around a cylinder produces:", ["Lift $F_y=-\\rho U\\Gamma$ per unit length, and still zero drag", "Drag but no lift", "Both lift and drag", "Neither lift nor drag"], 0, "$F_y=-\\rho U\\Gamma$ " + KNOW + "\nDeriving it means integrating the surface pressure, so it's the one result you may quote.\nWith Γ > 0 counter-clockwise, $F_y<0$ (downward). Clockwise circulation gives upward lift.", s11, fig="rot_cyl_lt1")
mcq("pf-18", T, "For a rotating cylinder, as $\\Gamma/(4\\pi Ua)$ increases beyond 1, the stagnation point:", ["Leaves the surface and moves into the flow", "Moves to the front of the cylinder", "Splits into four points", "Disappears"], 0, "On the surface, $v_r=0$ always. Set $v_\\theta=0$:\n$-2U\\sin\\theta+\\dfrac{\\Gamma}{2\\pi a}=0$ (cylinder + vortex rows " + S2 + ")\n$\\sin\\theta_{stag}=\\dfrac{\\Gamma}{4\\pi Ua}$\nWhen the ratio is above 1, there's no solution on $r=a$, so the stagnation point lifts off the body.", s11, fig="rot_cyl_gt1")
tf("pf-19", T, "The Magnus effect is lift on a rotating body in a crossflow, e.g. a curving soccer ball.", True, "Rotation adds circulation. Circulation in a uniform stream gives lift ($F_y=-\\rho U\\Gamma$ " + KNOW + ").", s11, fig="rot_cyl_eq1")
sa("pf-20", T, "For the half-body, derive the stagnation distance $b$ upstream of the source.", "On the negative $x$-axis: $u=U-\\dfrac{m}{2\\pi b}=0$, so $b=\\dfrac{m}{2\\pi U}$.", "Uniform: $u=U$ (uniform row " + S2 + ")\nSource at $\\theta=\\pi$: $v_r=\\frac{m}{2\\pi b}$ outward, which points in $-x$ (source row " + S2 + ")\nStagnation: the two velocities cancel\n$b=\\dfrac{m}{2\\pi U}$ (derived)", s9, ["u = U − m/(2πb) = 0", "b = m/(2πU)"], fig="half_body")
sa("pf-21", T, "For the cylinder (uniform + doublet), how do you show the doublet strength must make $\\psi=0$ on $r=a$?", "$\\psi=Ur\\sin\\theta-\\dfrac{K\\sin\\theta}{r}$. Setting $\\psi=0$ at $r=a$ for every θ gives $K=Ua^2$, so $\\psi=U\\sin\\theta\\,(r-a^2/r)$.", "$r=a$ must be a streamline (the body), and $\\psi=0$ on the dividing streamline.\n$Ua\\sin\\theta-\\frac{K}{a}\\sin\\theta=0$\n$K=Ua^2$ (derived; $K$ = doublet strength in ψ form, sheet doublet row " + S2 + ")", s10, ["ψ = 0 on r = a", "K = Ua²"], fig="cylinder")
sa("pf-22", T, "Derive the surface pressure coefficient on a cylinder in potential flow.", "$C_p=\\dfrac{p_s-p_0}{\\tfrac12\\rho U^2}=1-4\\sin^2\\theta$", "Bernoulli from far upstream (0) to the surface (s) " + S1 + ":\n$p_0+\\tfrac12\\rho U^2=p_s+\\tfrac12\\rho v_{\\theta s}^2$ (horizontal, γz cancels; $v_r=0$ on the body)\n$v_{\\theta s}=-2U\\sin\\theta$ (derived, put $r=a$)\n$C_p=1-\\dfrac{v_{\\theta s}^2}{U^2}=1-4\\sin^2\\theta$", s10, ["Bernoulli ∞ → surface", "v_θs = −2U sinθ", "1 − 4 sin²θ"], fig="cylinder")
sa("pf-23", T, "For the Rankine oval (source $+m$ at $x=-a$, sink $-m$ at $x=+a$), derive the half-length $\\ell$.", "On the $x$-axis at $x=\\ell$: $U+\\dfrac{m}{2\\pi(\\ell+a)}-\\dfrac{m}{2\\pi(\\ell-a)}=0$, which gives $\\ell^2=a^2+\\dfrac{ma}{\\pi U}$.", "Add the three $u$'s on the axis (uniform, source, sink rows " + S2 + ").\nSet the sum to 0 at the stagnation point.\nMultiply through by $(\\ell^2-a^2)$:\n$\\ell^2=a^2+\\dfrac{ma}{\\pi U}$ (derived; checked symbolically)", s10, ["add the three u's", "ℓ² = a² + ma/(πU)"], fig="rankine_oval")
mcq("pf-24", T, "For $\\Gamma/(4\\pi Ua)=1$, where is the stagnation point?", ["A single point at the bottom of the cylinder ($\\theta=-90^\\circ$)", "Two points on the upper surface", "Off the body, above it", "At the front and rear"], 0, "$\\sin\\theta_{stag}=\\Gamma/(4\\pi Ua)$ (derived, see the rotating-cylinder card).\nWith the sketch's sign (circulation giving upward lift), the two surface points merge at the bottom.", s11, fig="rot_cyl_eq1")

# ───────────────────────── 6.8–6.9 Navier–Stokes & exact solutions ─────────────────────────
T = "Navier–Stokes & exact solutions (6.8–6.9)"; s11 = L(11, "Navier–Stokes"); s12 = L(12, "Viscous Flow"); s13 = L("13-14", "Viscous Flow Examples")
mcq("ns-01", T, "The Navier–Stokes equations are:", ["Second-order, nonlinear PDEs with no general analytical solution", "First-order linear ODEs", "Linear PDEs that can be superposed", "Algebraic equations"], 0, "NS ($x$ Cartesian, $z$ cylindrical) " + S1 + ".\nThe convective terms ($u\\,\\partial u/\\partial x$ …) make them nonlinear.", s11)
sa("ns-02", T, "Name three cases where Navier–Stokes has analytical solutions.", "(1) Potential flow. (2) Fully developed parallel flows (the convective terms vanish), e.g. pipe, channel, falling film. (3) Stokes (creeping) flow.", "The sheet gives the parallel-flow forms directly " + S1 + ":\n$\\dfrac{dp}{dx}=\\mu\\dfrac{d^2u}{dy^2}$ (plates)\n$\\dfrac{dp}{dz}=\\mu\\dfrac1r\\dfrac{d}{dr}\\left(r\\dfrac{dv_z}{dr}\\right)$ (pipe)\n$\\mu\\dfrac{d^2u}{dy^2}+\\rho g\\sin\\theta=0$ (falling film)", s11, ["potential flow", "fully developed parallel", "creeping flow"])
mcq("ns-03", T, "For incompressible 3-D viscous flow, Navier–Stokes plus continuity give:", ["4 equations for 4 unknowns ($u, v, w, p$)", "3 equations for 3 unknowns", "4 equations for 3 unknowns", "1 equation for 1 unknown"], 0, "3 momentum equations + continuity.", s11)
tf("ns-04", T, "For a Newtonian incompressible fluid, the viscous stresses are linearly proportional to the strain rates.", True, "$\\tau_{yx}=\\mu\\left(\\dfrac{\\partial u}{\\partial y}+\\dfrac{\\partial v}{\\partial x}\\right)$ " + S1 + "\nSubstituting this into Cauchy's equations gives Navier–Stokes.", s11)
mcq("ns-05", T, "The no-slip condition says that at a solid wall:", ["The fluid velocity equals the wall velocity", "The shear stress is zero", "The normal velocity is maximum", "The pressure is zero"], 0, "Stationary wall: $u=v=0$ there.", s11)
mcq("ns-06", T, "At a free surface (free-slip condition), which holds?", ["The shear stress is zero", "The velocity is zero", "The pressure gradient is infinite", "The vorticity is maximum"], 0, "$\\tau=\\mu\\,du/dy=0$, so $du/dy=0$ at the surface.\nThe pressure there is atmospheric.", s11)
sa("ns-07", T, "What two conditions hold at the interface between two immiscible fluids?", "Equal velocities on both sides, and equal shear stress parallel to the interface.", "$\\mu_1\\,du_1/dy=\\mu_2\\,du_2/dy$ at the interface.\nTogether these couple the two velocity profiles.", s11, ["equal velocity", "equal shear stress"])
mcq("ns-08", T, "Steady, fully developed laminar flow between two fixed parallel plates has a velocity profile that is:", ["Parabolic, with maximum at the centreline", "Linear", "Uniform", "Logarithmic"], 0, "Start from $\\dfrac{dp}{dx}=\\mu\\dfrac{d^2u}{dy^2}$ " + S1 + "\nIntegrate twice, then apply $u=0$ at $y=\\pm h$:\n$u=\\dfrac{1}{2\\mu}\\dfrac{dp}{dx}(y^2-h^2)$", s12)
tf("ns-09", T, "In pressure-driven flow between fixed plates, $dp/dx$ is negative in the flow direction.", True, "$u=\\frac{1}{2\\mu}\\frac{dp}{dx}(y^2-h^2)$ and $(y^2-h^2)<0$ between the plates.\nSo $u>0$ (flow in $+x$) needs $dp/dx<0$: pressure falls downstream.", s12)
mcq("ns-10", T, "Couette flow with zero pressure gradient between a fixed plate ($y=0$) and a plate moving at $U$ ($y=b$) has velocity profile:", ["$u=Uy/b$ (linear)", "Parabolic", "Logarithmic", "Uniform"], 0, "$\\dfrac{dp}{dx}=\\mu\\dfrac{d^2u}{dy^2}=0$ " + S1 + "\n$u=C_1y+C_2$\n$u(0)=0$ gives $C_2=0$. $u(b)=U$ gives $C_1=U/b$.\nA nonzero $dp/dx$ adds a parabola on top.", s13)
mcq("ns-11", T, "Hagen–Poiseuille (laminar pipe) flow has volume flow rate:", ["$Q=\\dfrac{\\pi R^4\\Delta p}{8\\mu\\ell}$", "$Q=\\dfrac{\\pi R^2\\Delta p}{8\\mu\\ell}$", "$Q=\\dfrac{\\pi D^4\\Delta p}{8\\mu\\ell}$", "$Q=\\dfrac{\\pi R^4\\Delta p}{4\\mu\\ell}$"], 0, "From the pipe form $\\frac{dp}{dz}=\\mu\\frac1r\\frac{d}{dr}(r\\frac{dv_z}{dr})$ " + S1 + ":\nintegrate twice → $v_z=\\frac{1}{4\\mu}\\frac{dp}{dz}(r^2-R^2)$\n$Q=\\int_0^R v_z\\,2\\pi r\\,dr$\nwith $-dp/dz=\\Delta p/\\ell$ (derived)\nHalving $R$ cuts $Q$ by 16.", s13)
tf("ns-12", T, "In laminar pipe flow, the average velocity is half the centreline velocity.", True, "$V_{avg}=\\dfrac{Q}{\\pi R^2}=\\dfrac{R^2}{8\\mu}\\dfrac{\\Delta p}{\\ell}$\n$u_{max}=v_z(0)=\\dfrac{R^2}{4\\mu}\\dfrac{\\Delta p}{\\ell}$\nRatio = 1/2 (derived).", s13)

# ───────────────────────── Ch 8 Pipe flow ─────────────────────────
T = "Pipe flow & turbulence (Ch 8)"; s15 = L(15, "Viscous Flow in Pipes"); s16 = L(16, "Viscous Flow in Pipes"); s17 = L(17, "Viscous Flow in Pipes")
mcq("pp-01", T, "For pipe flow, with Re based on $D$ and average velocity, the flow is typically laminar below:", ["Re ≈ 2100", "Re ≈ 500", "Re ≈ 5×10⁵", "Re ≈ 10,000"], 0, "Laminar < 2100. Transitional 2100–4000. Turbulent > 4000.\n$\\mathrm{Re}=\\rho VD/\\mu$ " + DEF, s15)
tf("pp-02", T, "The distinguishing feature of turbulence is random velocity fluctuations.", True, "That's why the velocity is split as $u=\\bar u+u'$ (Reynolds decomposition).", s15)
mcq("pp-03", T, "Reynolds decomposition splits an instantaneous variable into:", ["A time-mean part plus a fluctuating part", "A laminar part plus a turbulent part", "A pressure part plus a viscous part", "Normal and shear components"], 0, "$u=\\bar u+u'$ " + DEF + "\n$\\overline{u'}=0$", s15)
mcq("pp-04", T, "Turbulence intensity is defined as:", ["$u'_{rms}/\\bar u$", "$\\bar u/u'_{rms}$", "$\\overline{u'v'}$", "$\\bar u/U_{max}$"], 0, "$I=\\sqrt{\\overline{u'^2}}\\,/\\,\\bar u$ " + DEF, s15)
tf("pp-05", T, "The time average of a fluctuation is zero, but the time average of a product of two fluctuations, $\\overline{u'v'}$, generally is not.", True, "That nonzero correlation is the Reynolds shear stress $-\\rho\\overline{u'v'}$.", s15)
mcq("pp-06", T, "Averaging the Navier–Stokes equations (RANS) creates extra unknowns called:", ["Reynolds stresses $-\\rho\\overline{u_i'u_j'}$", "Viscous stresses", "Body forces", "Pressure fluctuations only"], 0, "Diagonal terms = normal Reynolds stresses.\nOff-diagonal terms = Reynolds shear stresses.", s15)
sa("pp-07", T, "What is the turbulence closure problem?", "RANS has more unknowns than equations: 4 mean variables + 6 Reynolds stresses (10) vs 4 equations. The Reynolds stresses must be modelled, e.g. with an eddy viscosity.", "No exact equation for the new unknowns exists without creating even more unknowns.", s15, ["more unknowns than equations", "model Reynolds stresses"])
mcq("pp-08", T, "In the eddy-viscosity model, the total shear stress in turbulent flow is:", ["$\\tau=(\\mu+\\eta)\\,d\\bar u/dy$", "$\\tau=\\mu\\,d\\bar u/dy$ only", "$\\tau=-\\rho\\overline{u'v'}$ only", "$\\tau=\\rho\\bar u^2$"], 0, "$-\\rho\\overline{u'v'}=\\eta\\,\\dfrac{d\\bar u}{dy}$ " + DEF + "\n$\\eta$ = eddy viscosity: a property of the flow, not the fluid.", s16)
mcq("pp-09", T, "From the wall outward, the layers of a turbulent pipe profile are:", ["Viscous sublayer → overlap (log) layer → outer layer", "Outer → viscous sublayer → overlap", "Laminar → transition → wake", "Boundary layer → core → wake"], 0, "Viscous sublayer: viscous stress dominates.\nOuter layer: turbulent stress dominates.\nOverlap: log law.", s16)
tf("pp-10", T, "A turbulent pipe profile is flatter across the core than the laminar parabola, with a steeper gradient at the wall.", True, "Turbulent mixing evens out the core.\nThe steeper $du/dy$ at the wall means larger wall shear $\\tau_w$.", s16)
mcq("pp-11", T, "The quantity $u^*=\\sqrt{\\tau_w/\\rho}$ is the:", ["Friction velocity", "Free-stream velocity", "Average velocity", "Fluctuation RMS"], 0, "$u^*$ " + DEF + "\nIt scales the velocity near the wall in the log law.", s16)
mcq("pp-12", T, "In fully developed turbulent pipe flow, the friction factor $f$ depends on:", ["Reynolds number and relative roughness $\\varepsilon/D$", "Reynolds number only", "Relative roughness only", "Pipe length only"], 0, "Colebrook " + S2 + ":\n$\\dfrac{1}{\\sqrt f}=-2\\log\\left(\\dfrac{\\varepsilon}{3.7065D}+\\dfrac{2.5226}{\\mathrm{Re}\\sqrt f}\\right)$\nLaminar: $f=64/\\mathrm{Re}$ " + S2 + " (no roughness term).", s16)
tf("pp-13", T, "Wall roughness has a negligible effect on $f$ in laminar pipe flow.", True, "$f=64/\\mathrm{Re}$ " + S2 + ": no $\\varepsilon$ in it.\nViscous effects fill the whole pipe and swamp small roughness.", s16)
sa("pp-14", T, "Why does roughness matter in turbulent flow but not laminar flow?", "In turbulent flow the viscous sublayer is very thin, so roughness elements poke through it into the turbulent region. In laminar flow, viscosity dominates the whole cross-section.", "This is the basis for the terms smooth, transitionally rough and fully rough.", s16, ["thin viscous sublayer", "roughness protrudes"])
mcq("pp-15", T, "At very high Re (fully rough) on the Moody chart, $f$:", ["Depends only on $\\varepsilon/D$", "Keeps falling like $64/\\mathrm{Re}$", "Rises linearly with Re", "Goes to zero"], 0, "In Colebrook " + S2 + ", the $\\mathrm{Re}$ term vanishes as $\\mathrm{Re}\\to\\infty$, leaving $\\varepsilon/D$.", s16)
mcq("pp-16", T, "The Blasius correlation $f=0.316/\\mathrm{Re}^{1/4}$ applies to:", ["Turbulent flow in smooth pipes (Re ≲ 10⁵)", "Laminar flow", "Fully rough pipes", "Non-circular ducts only"], 0, "Blasius " + DEF + ". It's not on the sheet, so on the exam use Colebrook " + S2 + ".", s16)
mcq("pp-17", T, "Major head loss in a pipe (Darcy–Weisbach) is:", ["$h_{major}=f\\dfrac{\\ell}{D}\\dfrac{V^2}{2g}$", "$h_{major}=K_L\\dfrac{V^2}{2g}$", "$h_{major}=\\dfrac{32\\mu\\ell V}{D}$", "$h_{major}=f\\dfrac{D}{\\ell}\\dfrac{V^2}{2g}$"], 0, "$h_{major}=f\\frac{\\ell}{D}\\frac{V^2}{2g}$ " + DEF + "\n$h_{minor}=K_L\\frac{V^2}{2g}$ " + DEF + "\nBoth go on the right side of the sheet's energy equation " + S2 + ".", s16)
tf("pp-18", T, "Bernoulli can be applied directly to viscous pipe flow as long as the flow is steady.", False, "Bernoulli assumes frictionless flow.\nUse the energy equation with $\\sum h_{major}+\\sum h_{minor}$ " + S2 + " (plus pump or turbine terms).", s16)
mcq("pp-19", T, "The hydraulic diameter of a non-circular duct is:", ["$D_h=4A/P$", "$D_h=A/P$", "$D_h=2A/P$", "$D_h=\\sqrt{4A/\\pi}$"], 0, "$D_h=4A/P$ " + DEF + " ($A$ = area, $P$ = wetted perimeter).\nCheck with a circle: $4(\\pi D^2/4)/(\\pi D)=D$.", s17)
mcq("pp-20", T, "In the energy equation for pipe flow, a pump appears as:", ["A head added between points 1 and 2 (a gain)", "A head loss, like friction", "A change in elevation", "It doesn't appear"], 0, "Sheet energy equation " + S2 + ":\n$\\left(\\frac{p_1}{\\rho}+\\alpha_1\\frac{\\bar V_1^2}{2}+gz_1\\right)-\\left(\\frac{p_2}{\\rho}+\\alpha_2\\frac{\\bar V_2^2}{2}+gz_2\\right)=\\sum h_{major}+\\sum h_{minor}$\nA pump adds energy to the left side. A turbine removes it.\n$\\alpha$ = kinetic-energy correction factor (2 for laminar, ≈1 for turbulent).", s17)
tf("pp-21", T, "For pipes in series, the flow rate is the same in each pipe and the head losses add.", True, "For parallel pipes it's reversed: the head loss is the same in each branch and the flow rates add.", s17)
sa("pp-22", T, "For a single pipe, which unknown ($\\Delta p$, $D$ or $Q$) can be found without iteration?", "$\\Delta p$ (or head loss) when $L$, $D$ and $Q$ are given. Finding $D$ or $Q$ needs iteration, because $f$ depends on the unknown through Re and $\\varepsilon/D$.", "Iterate between the energy equation " + S2 + " and Colebrook " + S2 + ".", s17, ["Δp direct", "D and Q iterate"])
tf("pp-23", T, "Pressure drop in fully developed pipe flow is proportional to pipe length.", True, "$h_{major}\\propto\\ell/D$ " + DEF + ".", s16)

# ───────────────────────── Ch 9 External flow ─────────────────────────
T = "External flow & boundary layers (Ch 9)"; s18 = L(18, "Flow over Immersed Bodies"); s19 = L(19, "Flow over Immersed Bodies")
mcq("ex-01", T, "Drag is the component of the resultant fluid force:", ["Parallel to the upstream flow direction", "Perpendicular to the upstream flow", "Normal to the body surface", "Due only to shear stress"], 0, "Lift is perpendicular to the free stream.", s18)
sa("ex-02", T, "Lift and drag come from integrating which two surface quantities over the body?", "Pressure (acting normal to the surface) and wall shear stress (acting tangential to the surface).", "Drag = pressure (form) drag + friction drag.", s18, ["pressure", "wall shear stress"])
mcq("ex-03", T, "The drag coefficient is defined through:", ["$D=A_D\\left(\\tfrac12\\rho V_\\infty^2\\right)C_D$", "$D=A_D\\,\\rho V_\\infty^2C_D$", "$D=\\tfrac12\\rho V_\\infty C_D$", "$D=A_D V_\\infty^2/C_D$"], 0, "Immersed bodies row " + S2 + ".\n$A_D$ = frontal area (bluff bodies) or planform area (wings).\nLift: $L=A_L\\left(\\tfrac12\\rho V_\\infty^2\\right)C_L$ " + S2, s18)
tf("ex-04", T, "The fluid forces on a body are the same whether it moves through still fluid or the fluid moves past it at the same relative speed.", True, "Only relative motion matters, which is why wind tunnels work.", s18)
mcq("ex-05", T, "The boundary-layer thickness δ is usually defined as the distance from the wall where:", ["$u=0.99U$", "$u=0.5U$", "$u=U$ exactly", "The shear stress is maximum"], 0, "$\\delta$ at 99% " + DEF + ".\n$\\delta^*$ and $\\theta$ are integral measures.", s19)
mcq("ex-06", T, "Using the formula sheet, the laminar flat-plate boundary-layer thickness is:", ["$\\dfrac{\\delta}{x}=\\dfrac{5.48}{\\sqrt{\\mathrm{Re}_x}}$", "$\\dfrac{\\delta}{x}=\\dfrac{0.382}{\\mathrm{Re}_x^{1/5}}$", "$\\dfrac{\\delta}{x}=\\dfrac{0.730}{\\sqrt{\\mathrm{Re}_x}}$", "$\\dfrac{\\delta}{x}=\\dfrac{64}{\\mathrm{Re}_x}$"], 0, "Boundary layer row " + S2 + ":\nlaminar $\\delta/x=5.48/\\sqrt{\\mathrm{Re}_x}$\nturbulent $\\delta/x=0.382/\\mathrm{Re}_x^{1/5}$\n$\\mathrm{Re}_x=Ux/\\nu$\nSo δ grows like $\\sqrt x$ (laminar) and $x^{4/5}$ (turbulent).", s19)
mcq("ex-07", T, "Transition to turbulence on a smooth flat plate typically occurs near:", ["$\\mathrm{Re}_x\\approx5\\times10^5$", "$\\mathrm{Re}_x\\approx2100$", "$\\mathrm{Re}_x\\approx4000$", "$\\mathrm{Re}_x\\approx10^9$"], 0, "Typical value " + DEF + ". It ranges from $2\\times10^5$ to $3\\times10^6$, depending on roughness and free-stream turbulence.", s19)
tf("ex-08", T, "Momentum thickness θ represents the loss of momentum flux in the boundary layer compared with inviscid flow.", True, "$\\theta=\\int_0^\\infty\\frac uU\\left(1-\\frac uU\\right)dy$ " + DEF, s19)
tf("ex-09", T, "Wall shear stress on a flat plate in laminar flow decreases with distance from the leading edge.", True, "$C_f=\\dfrac{\\tau_w}{\\tfrac12\\rho U^2}=\\dfrac{0.730}{\\sqrt{\\mathrm{Re}_x}}$ " + S2 + "\n$\\mathrm{Re}_x\\propto x$, so $\\tau_w\\propto x^{-1/2}$: it shrinks as the BL thickens.", s19)
mcq("ex-10", T, "For a streamlined body (thin airfoil at small angle of attack), most of the drag is:", ["Friction drag", "Pressure (form) drag", "Wave drag", "Separation drag"], 0, "Bluff bodies (cylinders, plates normal to the flow) are dominated by pressure drag.", s19)
mcq("ex-11", T, "Boundary-layer separation is caused by:", ["An adverse pressure gradient ($dp/dx>0$) slowing near-wall fluid until $\\partial u/\\partial y=0$ at the wall", "A favourable pressure gradient", "Free-stream turbulence alone", "Compressibility"], 0, "$dp/dx>0$ means pressure rises downstream and pushes back on the slow fluid near the wall.\nPast separation: reversed flow and a wake.", s19)
tf("ex-12", T, "A turbulent boundary layer resists separation better than a laminar one.", True, "Mixing brings high-momentum fluid down to the wall. That's why golf-ball dimples reduce drag.", s19)
mcq("ex-13", T, "The sudden drop in $C_D$ for a smooth sphere around Re ≈ 3×10⁵ happens because:", ["The BL becomes turbulent, separation moves aft and the wake narrows", "The flow becomes laminar everywhere", "Friction drag disappears", "The sphere starts rotating"], 0, "This is the drag crisis.\nThe sheet's correlation $C_D=0.44$ holds only up to $\\mathrm{Re}=2\\times10^5$ " + S2 + ". Above that, $C_D$ falls sharply.", s19)
tf("ex-14", T, "Golf-ball dimples reduce drag by triggering an earlier transition to a turbulent boundary layer.", True, "Delayed separation → narrower wake → less pressure drag.", s19)
mcq("ex-15", T, "An airfoil stalls when, at high angle of attack:", ["The flow separates from the upper surface, lift drops and drag rises", "The flow becomes supersonic", "The lower-surface pressure drops", "The BL becomes laminar"], 0, "$C_L$ peaks at the stall angle. Lab 4 measured the $C_p$ distribution on an airfoil.", s19)
mcq("ex-16", T, "For a sphere at Re < 0.1 (creeping flow), the sheet gives:", ["$C_D=24/\\mathrm{Re}$", "$C_D=0.44$", "$C_D=18.5/\\mathrm{Re}^{0.6}$", "$C_D=64/\\mathrm{Re}$"], 0, "Sphere rows " + S2 + ":\nRe < 0.1: $C_D=24/\\mathrm{Re}$\n2 < Re < 500: $C_D=18.5/\\mathrm{Re}^{0.6}$\n500 < Re < 2×10⁵: $C_D=0.44$\nWith $C_D=24/\\mathrm{Re}$, drag is linear in $V$ (Stokes' law, $F_D=3\\pi\\mu VD$).", s19)
tf("ex-17", T, "For turbulent flow on a flat plate, the sheet gives $C_f=0.0594/\\mathrm{Re}_x^{1/5}$.", True, "Boundary layer row " + S2 + ".\nCompare laminar $C_f=0.730/\\sqrt{\\mathrm{Re}_x}$ " + S2 + ".", s19)

# ───────────────────────── Ch 11 Compressible ─────────────────────────
T = "Compressible flow (Ch 11)"; s = "Course outline – Ch 11 (11.1–11.6)"
mcq("cf-01", T, "The speed of sound in an ideal gas is:", ["$c=\\sqrt{kRT}$", "$c=\\sqrt{RT}$", "$c=kRT$", "$c=\\sqrt{p}$"], 0, "$c=\\sqrt{kRT}$ " + S3 + "\n$k=c_p/c_v$ (1.4 for air)\n$T$ in kelvin\nAir at 288 K: $c\\approx340\\ \\mathrm{m/s}$.", s)
mcq("cf-02", T, "Flow is usually treated as incompressible when the Mach number is below about:", ["0.3", "1.0", "0.8", "0.05"], 0, "$M=V/c$ " + S3 + ".\nBelow 0.3, density changes are under about 5%.", s)
tf("cf-03", T, "In isentropic subsonic flow through a converging duct, velocity increases and pressure decreases.", True, "Area–velocity relation " + S3 + ":\n$\\dfrac{dV}{V}=-\\dfrac{dA}{A}\\dfrac{1}{1-M^2}$\nFor $M<1$ and $dA<0$: $dV>0$ (it speeds up).", s)
tf("cf-04", T, "In supersonic flow, a diverging duct accelerates the flow.", True, "$\\frac{dV}{V}=-\\frac{dA}{A}\\frac{1}{1-M^2}$ " + S3 + "\nFor $M>1$, $(1-M^2)<0$, so $dA>0$ gives $dV>0$.", s)
mcq("cf-05", T, "In isentropic flow, $M=1$ can only occur:", ["At the throat (minimum area)", "At the inlet", "Anywhere in a diverging section", "At the exit of any duct"], 0, "From the area relation " + S3 + ": $dA=0$ is required where $M=1$.\nGoing from subsonic to supersonic needs a converging–diverging nozzle.", s)
sa("cf-06", T, "What does it mean for a converging nozzle to be choked?", "$M=1$ at the exit (the throat). Lowering the back pressure further cannot increase the mass flow, which stays at its maximum for the given stagnation conditions.", "Critical ratios at the throat " + S3 + ":\n$\\dfrac{p_0}{p^*}=\\left(\\dfrac{k+1}{2}\\right)^{k/(k-1)}$ (≈1.893 for air)\n$\\dfrac{T_0}{T^*}=\\dfrac{k+1}{2}$", s, ["M = 1 at throat", "max mass flow", "back pressure no effect"])
tf("cf-07", T, "Stagnation temperature is constant in adiabatic flow of an ideal gas, even across a normal shock.", True, "$\\dfrac{T_0}{T}=1+\\dfrac{k-1}{2}M^2$ " + S3 + "\n$T_0$ changes only if heat or work is added.\nStagnation pressure, however, drops across a shock.", s)
mcq("cf-08", T, "Across a normal shock, the flow goes from:", ["Supersonic to subsonic, with a static-pressure rise and a stagnation-pressure loss", "Subsonic to supersonic", "Supersonic to more supersonic", "Subsonic to sonic, isentropically"], 0, "Shocks are irreversible: entropy rises, so $p_0$ falls.", s)
mcq("cf-09", T, "For air ($k=1.4$), the critical pressure ratio $p^*/p_0$ is about:", ["0.528", "0.833", "0.634", "1.893"], 0, "$\\dfrac{p_0}{p^*}=\\left(\\dfrac{k+1}{2}\\right)^{k/(k-1)}$ " + S3 + "\n$=1.2^{3.5}=1.893$\n$p^*/p_0=0.528$ (checked in Python).\n$T^*/T_0=0.833$ is the temperature ratio.", s)
